*{margin:0;padding:0;box-sizing:border-box;scroll-behavior:smooth}
:root{--purple:#a855ff;--purple2:#d68cff;--muted:#b9b1ca;--line:rgba(255,255,255,.12)}
body{font-family:Inter,Arial,sans-serif;color:white;background:#030108;overflow-x:hidden}
a{color:inherit;text-decoration:none}
.nav-wrap{
position:fixed;
top:0;
left:0;
width:100%;
z-index:999;
display:flex;
justify-content:center;
padding:22px 24px 0;
}
nav{
width:min(1210px,calc(100% - 88px));
height:78px;
padding:0 26px;
border:1px solid rgba(255,255,255,.20);
border-radius:34px;
background:
  linear-gradient(180deg,rgba(255,255,255,.13),rgba(255,255,255,.035)),
  rgba(12,8,24,.54);
backdrop-filter:blur(28px) saturate(160%);
-webkit-backdrop-filter:blur(28px) saturate(160%);
display:flex;
align-items:center;
justify-content:space-between;
box-shadow:
  inset 0 1px 0 rgba(255,255,255,.22),
  inset 0 -1px 0 rgba(255,255,255,.06),
  0 20px 70px rgba(0,0,0,.36),
  0 0 45px rgba(154,72,255,.18);
}
.logo{display:flex;align-items:center;gap:10px;font-size:24px;font-weight:900}.logo-mark{width:27px;height:27px;border-radius:50%;background:linear-gradient(135deg,#fff,#9b4dff);box-shadow:0 0 18px rgba(157,75,255,.6)}
.navlinks{display:flex;list-style:none;gap:52px;color:#d7d1e2;font-size:17px;font-weight:600}.navlinks a:hover{color:#c778ff}.nav-actions{display:flex;gap:22px;font-size:14px;font-weight:800;align-items:center}.signup{padding:12px 22px;border-radius:999px;border:1px solid rgba(255,255,255,.14);background:rgba(255,255,255,.045)}
.hero-wrap{min-height:100vh;position:relative;overflow:hidden;background:radial-gradient(circle at 72% 70%,rgba(112,19,255,.9),transparent 34%),radial-gradient(circle at 12% 100%,rgba(65,25,170,.65),transparent 28%),linear-gradient(180deg,#030108 0%,#07020f 58%,#210856 100%)}
.hero-wrap:before{content:"";position:absolute;inset:0;background-image:linear-gradient(rgba(255,255,255,.055) 1px,transparent 1px),linear-gradient(90deg,rgba(255,255,255,.055) 1px,transparent 1px);background-size:112px 112px;opacity:.45}
.tech-chip{position:absolute;border:1px solid rgba(185,108,255,.23);background:rgba(20,9,34,.48);backdrop-filter:blur(10px);border-radius:16px;padding:13px 18px;color:#dcb7ff;font-weight:800;font-size:13px;letter-spacing:.08em;box-shadow:0 0 30px rgba(138,55,255,.18);animation:chipFloat 6s ease-in-out infinite}
.chip1{right:12%;top:22%}.chip2{right:34%;top:18%;animation-delay:1s}.chip3{right:8%;bottom:24%;animation-delay:2s}@keyframes chipFloat{0%,100%{transform:translateY(0)}50%{transform:translateY(-16px)}}
.hero{max-width:1480px;margin:0 auto;position:relative;z-index:2;min-height:900px;padding:135px 10.5% 72px;display:grid;grid-template-columns:1.02fr .98fr;align-items:center;gap:30px}
.copy h1{font-size:clamp(60px,6.5vw,98px);line-height:.98;letter-spacing:-.07em;font-weight:900;max-width:720px;margin-bottom:30px}.copy h1 span{background:linear-gradient(180deg,#fff 0%,#eddaff 32%,#bd69ff 72%,#8d35ff 100%);-webkit-background-clip:text;color:transparent}
.hero-actions-main{display:flex;gap:34px;margin:28px 0 48px;align-items:center;flex-wrap:wrap}.btn{display:inline-flex;align-items:center;justify-content:center;padding:18px 42px;border-radius:13px;font-size:20px;font-weight:900;color:white;background:linear-gradient(180deg,#bd59ff,#7817e8);box-shadow:0 0 28px rgba(158,55,255,.75);border:0;cursor:pointer}.btn.outline{background:rgba(255,255,255,.055);border:1px solid rgba(255,255,255,.30);box-shadow:none;color:#e1dbe8}
.intro-text{color:var(--muted);font-size:22px;line-height:1.55;max-width:650px;margin-bottom:44px}.stats{display:flex;gap:62px;flex-wrap:wrap}.stat h3{font-size:42px;color:#d4a2ff;letter-spacing:-.04em;margin-bottom:8px}.stat p{font-size:24px;color:#e7ddf2;text-transform:uppercase}
.visual{min-height:650px;display:flex;align-items:center;justify-content:center}.mascot{width:min(540px,92vw);position:relative;z-index:3;animation:floatMascot 4s ease-in-out infinite,glowPulse 2.8s ease-in-out infinite;transform-origin:center}@keyframes floatMascot{0%,100%{transform:translateY(0) rotate(0deg) scale(1)}25%{transform:translateY(-10px) rotate(-1deg) scale(1.015)}50%{transform:translateY(-22px) rotate(1deg) scale(1.03)}75%{transform:translateY(-10px) rotate(-.8deg) scale(1.015)}}@keyframes glowPulse{0%,100%{filter:drop-shadow(0 0 54px rgba(176,62,255,.45))}50%{filter:drop-shadow(0 0 92px rgba(198,91,255,.78))}}
.brand-strip{padding:75px 7%;background:#050408;border-top:1px solid rgba(255,255,255,.08);border-bottom:1px solid rgba(255,255,255,.08);text-align:center}.brand-strip small{color:#7b748b;letter-spacing:.42em;font-weight:900}.brands{display:flex;justify-content:center;gap:74px;flex-wrap:wrap;margin-top:48px;color:white;opacity:.62;font-size:26px;font-weight:900;filter:grayscale(1)}.brands span{letter-spacing:-.04em}
.section{position:relative;z-index:2;padding:115px 7%;background:radial-gradient(circle at 82% 10%,rgba(132,39,255,.35),transparent 28%),radial-gradient(circle at 12% 78%,rgba(88,21,184,.26),transparent 32%),linear-gradient(180deg,#120521 0%,#1b0737 52%,#090312 100%);border-top:1px solid rgba(255,255,255,.055)}.section.alt{background:radial-gradient(circle at 18% 18%,rgba(159,57,255,.26),transparent 30%),linear-gradient(180deg,#0a0314 0%,#1f0a3d 55%,#08030f 100%)}.section-inner{max-width:1480px;margin:0 auto}.center{text-align:center}.eyebrow{color:#d395ff;letter-spacing:.32em;font-weight:900;font-size:14px;margin-bottom:28px}.center h2,.agents-overview h2{font-size:clamp(42px,4.2vw,66px);line-height:1.08;letter-spacing:-.065em;margin-bottom:34px}.grad{background:linear-gradient(180deg,#f3ddff,#a43eff);-webkit-background-clip:text;color:transparent}
.circuit-section{padding:120px 7%;background:#050408;position:relative;overflow:hidden}.circuit-board{max-width:900px;height:720px;margin:0 auto;position:relative;display:grid;place-items:center}.circuit-board:before,.circuit-board:after{content:"";position:absolute;border-radius:50%;border:1px solid rgba(151,66,255,.18)}.circuit-board:before{width:640px;height:640px}.circuit-board:after{width:480px;height:480px}.circuit-line{position:absolute;width:2px;height:260px;background:linear-gradient(#9b45ff,transparent);transform-origin:bottom;top:100px;left:50%;opacity:.75;filter:drop-shadow(0 0 10px #9b45ff);animation:electric 2s linear infinite}.l1{transform:rotate(45deg)}.l2{transform:rotate(135deg)}.l3{transform:rotate(225deg)}.l4{transform:rotate(315deg)}.l5{transform:rotate(0deg)}.l6{transform:rotate(90deg)}@keyframes electric{0%{opacity:.25}50%{opacity:1}100%{opacity:.25}}.core{width:210px;height:210px;border-radius:50%;background:radial-gradient(circle,#401199,#12041e);display:grid;place-items:center;border:1px solid rgba(181,105,255,.35);box-shadow:0 0 80px rgba(153,55,255,.45);z-index:3}.core img{width:170px;animation:floatMascot 4s ease-in-out infinite}.orbit-chip{position:absolute;width:150px;height:110px;border:1px solid rgba(255,255,255,.10);background:rgba(255,255,255,.035);display:grid;place-items:center;text-align:center;font-weight:900;color:#d8b2ff;transform:rotate(-12deg);transition:.25s;z-index:4}.orbit-chip:hover{background:rgba(150,70,255,.18);box-shadow:0 0 40px rgba(155,70,255,.35);transform:scale(1.08) rotate(-8deg)}.oc1{top:65px;left:165px}.oc2{top:65px;right:165px}.oc3{bottom:100px;left:150px}.oc4{bottom:100px;right:150px}.oc5{top:305px;left:35px}.oc6{top:305px;right:35px}
.agents-overview{display:grid;grid-template-columns:.75fr 1.55fr;gap:90px;align-items:center}.agents-overview p{max-width:475px;color:#c6bdd6;font-size:21px;line-height:1.65;margin-bottom:44px}.cards{display:grid;grid-template-columns:repeat(3,1fr);gap:28px}.agent-card{min-height:300px;border-radius:34px;padding:40px;background:radial-gradient(circle at 18% 10%,rgba(255,255,255,.10),transparent 28%),linear-gradient(180deg,rgba(76,39,118,.92),rgba(42,15,73,.96));border:1px solid rgba(255,255,255,.12);display:flex;flex-direction:column;justify-content:space-between;transition:.25s ease;cursor:pointer}.agent-card:hover,.agent-card.active{transform:translateY(-8px);border-color:rgba(207,140,255,.46);box-shadow:0 28px 78px rgba(153,60,255,.24)}.icon{width:58px;height:58px;border-radius:18px;display:grid;place-items:center;color:#d9aaff;font-size:24px;font-weight:900;background:rgba(255,255,255,.075);border:1px solid rgba(255,255,255,.10)}.agent-card h3{font-size:25px;letter-spacing:-.04em;margin-bottom:14px}.agent-card p{color:#c4bbd3;font-size:18px;line-height:1.55}.arrow{width:46px;height:46px;border-radius:50%;border:1px solid rgba(255,255,255,.13);display:grid;place-items:center;color:#d7b3ff;font-size:20px}
.agent-detail{margin-top:70px;display:grid;grid-template-columns:1fr 1fr;gap:70px;align-items:center;padding:46px;border-radius:32px;border:1px solid rgba(255,255,255,.12);background:rgba(0,0,0,.16);backdrop-filter:blur(18px)}.num{color:var(--purple2);font-size:31px;font-weight:900;margin-bottom:22px}.agent-detail h2{font-size:clamp(42px,4vw,62px);line-height:1.05;letter-spacing:-.05em;margin-bottom:24px}.agent-detail p{color:#f3effa;font-size:22px;line-height:1.55;margin-bottom:26px}.checks{list-style:none;color:white;font-size:20px;line-height:2.15}.checks li{display:flex;gap:14px;align-items:flex-start}.checks li::before{content:"✓";min-width:25px;height:25px;border-radius:50%;display:inline-grid;place-items:center;color:#0b0512;background:linear-gradient(135deg,#e7c7ff,#a94cff);font-size:15px;font-weight:900;margin-top:8px;box-shadow:0 0 18px rgba(178,89,255,.35)}.mockup{border:1px solid rgba(255,255,255,.12);background:rgba(10,10,14,.75);border-radius:22px;padding:36px}.mockup-row{background:rgba(255,255,255,.065);border:1px solid rgba(255,255,255,.1);border-radius:13px;padding:20px;color:#eee;font-size:17px;margin:16px 0}.mockup-btn{background:linear-gradient(90deg,#a638ff,#9b37ed);border-radius:13px;padding:18px;text-align:center;font-size:20px;font-weight:900}
.grid-3,.grid-4,.results,.testimonials,.faq{display:grid;gap:26px}.grid-3,.results,.testimonials{grid-template-columns:repeat(3,1fr);max-width:1080px;margin:55px auto 0}.grid-4{grid-template-columns:repeat(4,1fr);max-width:1120px;margin:55px auto 0}.faq{grid-template-columns:repeat(2,1fr);max-width:1250px;margin:55px auto 0}.info-card,.result-card{background:linear-gradient(180deg,rgba(255,255,255,.07),rgba(255,255,255,.025));border:1px solid rgba(255,255,255,.12);padding:34px;border-radius:18px;transition:.25s ease}.info-card:hover,.result-card:hover{transform:translateY(-6px);border-color:rgba(198,108,255,.36);background:linear-gradient(180deg,rgba(85,40,124,.38),rgba(255,255,255,.025))}.info-card h3{font-size:21px;margin-bottom:14px}.info-card p{color:#aaa3bd;line-height:1.6;font-size:16px}.result-card{text-align:center}.result-card strong{color:#b973ff;font-size:58px}
.cta-final{text-align:center;padding:130px 7%;background:radial-gradient(circle at 50% 48%,rgba(142,48,255,.28),transparent 36%),linear-gradient(180deg,#08030f 0%,#160724 100%)}.cta-final small{color:#aaa2b6;letter-spacing:.35em;font-weight:900}.cta-final h2{margin:36px 0 42px;font-size:clamp(60px,7vw,110px);line-height:.95;letter-spacing:-.07em}.cta-final h2 span{color:#a84dff}.cta-actions{display:flex;justify-content:center;gap:24px;flex-wrap:wrap}.cta-mini{width:86px;margin-top:74px;animation:floatMascot 4s ease-in-out infinite}
.footer-top{background:#050208;border-top:1px solid rgba(255,255,255,.08);padding:90px 7%}.footer-grid{max-width:1480px;margin:auto;display:grid;grid-template-columns:1.4fr repeat(4,1fr);gap:70px}.footer-grid h3{font-size:36px;margin-bottom:28px}.footer-grid h4{font-size:24px;margin-bottom:26px}.footer-grid p,.footer-grid a{display:block;color:#c4bed6;font-size:21px;line-height:1.75;margin-bottom:8px}
@media(max-width:1100px){.hero,.agents-overview,.agent-detail,.footer-grid{grid-template-columns:1fr}.navlinks{display:none}.cards,.grid-3,.grid-4,.results,.testimonials,.faq{grid-template-columns:1fr}.circuit-board{height:600px;transform:scale(.8)}}@media(max-width:680px){.hero,.section{padding-left:6%;padding-right:6%}.copy h1{font-size:55px}.mascot{width:360px}.stats{gap:28px}.stat p{font-size:18px}.footer-grid p,.footer-grid a{font-size:17px}.brands{gap:26px;font-size:20px}.circuit-board{transform:scale(.55);margin:-90px auto}}

/* headline white first, gradient after */
.copy h1 span{background:none;-webkit-background-clip:initial;color:inherit;text-shadow:none}
.headline-white{
  color:#fff !important;
  background:none !important;
  -webkit-background-clip:initial !important;
  text-shadow:0 8px 40px rgba(255,255,255,.08);
}
.headline-grad{
  background:linear-gradient(180deg,#f2ddff 0%,#c77bff 48%,#8d42ff 100%) !important;
  -webkit-background-clip:text !important;
  color:transparent !important;
}

/* liquid clickable CTA in agent mockup */
.mockup-btn{
  cursor:pointer;
  user-select:none;
  transition:.25s ease;
  position:relative;
  overflow:hidden;
}
.mockup-btn:hover{
  transform:translateY(-3px);
  box-shadow:0 18px 42px rgba(166,56,255,.32);
}
.mockup-btn:active{
  transform:scale(.98);
}
.mockup-btn::after{
  content:"";
  position:absolute;
  top:0;
  left:-80%;
  width:45%;
  height:100%;
  background:linear-gradient(90deg,transparent,rgba(255,255,255,.35),transparent);
  transform:skewX(-18deg);
}
.mockup-btn:hover::after{
  animation:shineMove .9s ease;
}
@keyframes shineMove{
  from{left:-80%}
  to{left:130%}
}
.result-pop{
  margin-top:18px;
  padding:18px;
  border-radius:14px;
  border:1px solid rgba(205,130,255,.22);
  background:rgba(255,255,255,.055);
  color:#ead7ff;
  display:none;
  line-height:1.55;
}
.result-pop.show{display:block;animation:popIn .28s ease}
@keyframes popIn{from{opacity:0;transform:translateY(10px)}to{opacity:1;transform:translateY(0)}}


/* iOS-style liquid glass nav + moving toggle */
.navbar,
nav{
  position:relative;
  overflow:hidden;
  background:
    linear-gradient(135deg,rgba(255,255,255,.20),rgba(255,255,255,.055) 45%,rgba(255,255,255,.10)),
    rgba(38,24,74,.22) !important;
  backdrop-filter: blur(34px) saturate(190%) !important;
  -webkit-backdrop-filter: blur(34px) saturate(190%) !important;
  border:1px solid rgba(255,255,255,.28) !important;
  box-shadow:
    inset 0 1px 0 rgba(255,255,255,.36),
    inset 0 -1px 0 rgba(255,255,255,.08),
    0 22px 70px rgba(0,0,0,.35),
    0 0 45px rgba(170,90,255,.20) !important;
}

.navbar::before,
nav::before{
  content:"";
  position:absolute;
  inset:0;
  border-radius:inherit;
  background:
    radial-gradient(circle at 18% 20%,rgba(255,255,255,.34),transparent 22%),
    radial-gradient(circle at 80% 70%,rgba(137,100,255,.24),transparent 30%);
  opacity:.65;
  pointer-events:none;
}

.nav-links,
.navlinks{
  position:relative;
  isolation:isolate;
}

.liquid-toggle{
  position:absolute;
  z-index:-1;
  height:52px;
  border-radius:999px;
  background:
    radial-gradient(circle at 22% 18%,rgba(255,255,255,.36),transparent 24%),
    linear-gradient(135deg,rgba(255,255,255,.24),rgba(122,64,255,.22));
  border:1px solid rgba(255,255,255,.24);
  box-shadow:
    inset 0 1px 0 rgba(255,255,255,.40),
    inset 0 -12px 24px rgba(24,8,66,.18),
    0 10px 32px rgba(139,72,255,.24);
  backdrop-filter: blur(22px) saturate(180%);
  -webkit-backdrop-filter: blur(22px) saturate(180%);
  transition:
    left .55s cubic-bezier(.16,1,.3,1),
    width .55s cubic-bezier(.16,1,.3,1),
    transform .55s cubic-bezier(.16,1,.3,1);
  pointer-events:none;
}

.liquid-toggle::after{
  content:"";
  position:absolute;
  inset:0;
  border-radius:inherit;
  background:linear-gradient(120deg,transparent,rgba(255,255,255,.22),transparent);
  transform:translateX(-70%);
  animation:liquidShine 3.2s ease-in-out infinite;
}

@keyframes liquidShine{
  0%,60%{transform:translateX(-80%)}
  100%{transform:translateX(110%)}
}

.nav-links a,
.navlinks a{
  position:relative;
  z-index:1;
  padding:16px 18px;
  border-radius:999px;
  transition:color .25s ease, transform .25s ease;
}

.nav-links a:hover,
.navlinks a:hover{
  color:#fff !important;
  transform:translateY(-1px);
}

.nav-links a.active,
.navlinks a.active{
  color:#fff !important;
}

@keyframes liquidPop{
  0%{transform:scale(.94)}
  55%{transform:scale(1.06)}
  100%{transform:scale(1)}
}
.liquid-toggle.pop{
  animation:liquidPop .55s cubic-bezier(.16,1,.3,1);
}


/* pricing section */
.pricing-section{
  position:relative;
  z-index:3;
  padding:110px 7% 120px;
  background:
    radial-gradient(circle at 50% 8%, rgba(132,55,255,.22), transparent 28%),
    linear-gradient(180deg,#050408 0%,#090312 100%);
  border-top:1px solid rgba(255,255,255,.08);
}

.pricing-inner{
  max-width:1240px;
  margin:0 auto;
}

.pricing-title{
  text-align:center;
  margin-bottom:62px;
}

.pricing-title small{
  display:block;
  color:#d58cff;
  font-weight:900;
  letter-spacing:.28em;
  margin-bottom:22px;
}

.pricing-title h2{
  font-size:clamp(42px,4.6vw,68px);
  line-height:1;
  letter-spacing:-.065em;
  color:#fff;
}

.pricing-grid{
  display:grid;
  grid-template-columns:repeat(3,1fr);
  gap:28px;
}

.price-card{
  position:relative;
  min-height:480px;
  padding:42px;
  border-radius:34px;
  border:1px solid rgba(255,255,255,.16);
  background:
    linear-gradient(180deg,rgba(255,255,255,.075),rgba(255,255,255,.025)),
    rgba(18,14,25,.72);
  backdrop-filter:blur(26px) saturate(150%);
  -webkit-backdrop-filter:blur(26px) saturate(150%);
  box-shadow:
    inset 0 1px 0 rgba(255,255,255,.12),
    0 22px 70px rgba(0,0,0,.28);
  overflow:hidden;
  transition:.25s ease;
}

.price-card:hover{
  transform:translateY(-8px);
  border-color:rgba(202,120,255,.42);
  box-shadow:0 30px 90px rgba(150,60,255,.18);
}

.price-card.featured{
  border-color:rgba(201,108,255,.55);
  box-shadow:
    inset 0 1px 0 rgba(255,255,255,.16),
    0 0 70px rgba(160,60,255,.20);
}

.price-card.featured::before{
  content:"";
  position:absolute;
  inset:0;
  background:radial-gradient(circle at 55% 0%,rgba(180,90,255,.20),transparent 36%);
  pointer-events:none;
}

.popular{
  position:absolute;
  top:28px;
  right:28px;
  padding:8px 14px;
  border-radius:999px;
  background:linear-gradient(135deg,#7b35ff,#c154ff);
  color:white;
  font-size:12px;
  font-weight:900;
}

.price-card h3{
  font-size:28px;
  margin-bottom:28px;
  color:#c987ff;
}

.price{
  font-size:clamp(46px,4vw,64px);
  letter-spacing:-.07em;
  font-weight:900;
  color:#fff;
  margin-bottom:22px;
}

.price span{
  font-size:20px;
  letter-spacing:0;
  color:#a9a2b8;
  font-weight:700;
}

.price-card p{
  color:#bdb5ca;
  font-size:18px;
  line-height:1.55;
  margin-bottom:32px;
}

.price-card hr{
  border:0;
  border-top:1px solid rgba(255,255,255,.14);
  margin:28px 0;
}

.price-card ul{
  list-style:none;
  display:grid;
  gap:16px;
  color:#e8e2ef;
  font-size:17px;
  margin-bottom:46px;
}

.price-card li::before{
  content:"✓";
  color:#b85cff;
  border:2px solid #9b4dff;
  border-radius:50%;
  width:20px;
  height:20px;
  display:inline-grid;
  place-items:center;
  font-size:12px;
  font-weight:900;
  margin-right:12px;
}

.price-btn{
  position:absolute;
  left:42px;
  right:42px;
  bottom:38px;
  height:58px;
  border-radius:999px;
  display:flex;
  align-items:center;
  justify-content:center;
  font-size:18px;
  font-weight:900;
  border:1px solid rgba(255,255,255,.20);
  background:rgba(255,255,255,.075);
  box-shadow:inset 0 1px 0 rgba(255,255,255,.14);
  transition:.25s ease;
}

.price-btn:hover{
  transform:translateY(-3px);
  background:rgba(255,255,255,.12);
}

.price-btn.primary{
  background:linear-gradient(135deg,#8f35ff,#bd45ff);
  border:0;
  box-shadow:0 16px 42px rgba(150,60,255,.32);
}

@media(max-width:1000px){
  .pricing-grid{grid-template-columns:1fr}
  .price-card{min-height:430px}
}


/* fix stats + real-looking brand logo row */
.stats{
  display:grid !important;
  grid-template-columns:repeat(3, minmax(120px,1fr)) !important;
