/* CURSOR AURA ORB + TOOPAI ASK POPUP */
.cursor-orb,
.cursor-orb-small{
  position:fixed;
  left:0;
  top:0;
  pointer-events:none;
  border-radius:50%;
  z-index:10000;
  opacity:0;
  transform:translate(-50%,-50%);
  mix-blend-mode:screen;
}

.cursor-orb{
  width:140px;
  height:140px;
  background:
    conic-gradient(from 0deg, rgba(109,93,255,.0), rgba(72,151,255,.45), rgba(213,73,255,.62), rgba(255,87,205,.42), rgba(72,151,255,.45), rgba(109,93,255,.0));
  filter:blur(18px);
  animation:orbSpin 3.8s linear infinite;
}

.cursor-orb-small{
  width:18px;
  height:18px;
  background:radial-gradient(circle,#fff 0%,#d68cff 34%,#6bc8ff 68%,transparent 72%);
  box-shadow:
    0 0 18px rgba(214,140,255,.9),
    0 0 34px rgba(87,170,255,.55);
}

@keyframes orbSpin{
  to{rotate:360deg}
}

.toopai-chat-widget{
  position:fixed;
  right:22px;
  bottom:24px;
  z-index:9998;
  font-family:Inter,Arial,sans-serif;
}

.toopai-chat-button{
  width:74px;
  height:74px;
  border-radius:50%;
  border:1px solid rgba(220,160,255,.32);
  background:
    radial-gradient(circle at 30% 22%,rgba(255,255,255,.28),transparent 28%),
    linear-gradient(135deg,rgba(149,57,255,.92),rgba(64,110,255,.78),rgba(255,71,203,.82));
  box-shadow:
    0 0 34px rgba(171,76,255,.45),
    0 18px 50px rgba(0,0,0,.38);
  color:white;
  display:grid;
  place-items:center;
  font-size:32px;
  cursor:pointer;
  animation:chatFloat 4s ease-in-out infinite;
}

@keyframes chatFloat{
  0%,100%{transform:translateY(0)}
  50%{transform:translateY(-8px)}
}

.toopai-chat-panel{
  position:absolute;
  right:0;
  bottom:92px;
  width:min(360px, calc(100vw - 34px));
  border-radius:28px;
  border:1px solid rgba(255,255,255,.18);
