/* PRELOADER + SMART TOOPAI AI + MOVING BRANDS */
.toopai-preloader{
  position:fixed;
  inset:0;
  z-index:20000;
  display:grid;
  place-items:center;
  background:
    radial-gradient(circle at 50% 48%,rgba(130,39,255,.62),transparent 30%),
    linear-gradient(120deg,#050109,#23005c,#5a0dd8,#12001f);
  background-size:220% 220%;
  animation:preBg 4.8s ease-in-out infinite;
  overflow:hidden;
  transition:opacity .75s ease, transform .9s ease;
}
.toopai-preloader.hide{
  opacity:0;
  transform:scale(1.12);
  pointer-events:none;
}
.toopai-preloader::before{
  content:"";
  position:absolute;
  inset:-20%;
  background:
    linear-gradient(90deg,transparent,rgba(195,95,255,.34),transparent) 20% 30%/55% 2px no-repeat,
    linear-gradient(90deg,transparent,rgba(90,160,255,.30),transparent) 65% 55%/48% 2px no-repeat,
    linear-gradient(180deg,transparent,rgba(255,100,220,.24),transparent) 42% 10%/2px 60% no-repeat;
  filter:drop-shadow(0 0 16px rgba(185,90,255,.75));
  animation:electricSweep 2.6s linear infinite;
}
@keyframes preBg{0%,100%{background-position:0% 50%}50%{background-position:100% 50%}}
@keyframes electricSweep{0%{transform:translateX(-6%) rotate(0deg);opacity:.45}50%{opacity:1}100%{transform:translateX(6%) rotate(1deg);opacity:.45}}
.preloader-card{
  position:relative;
  text-align:center;
  display:grid;
  place-items:center;
  gap:20px;
}
.preloader-mascot{
  width:190px;
  height:190px;
  border-radius:50%;
  display:grid;
  place-items:center;
  background:radial-gradient(circle,rgba(112,38,255,.42),rgba(8,1,20,.22) 68%);
  box-shadow:0 0 80px rgba(190,80,255,.70), inset 0 0 40px rgba(255,255,255,.08);
  animation:preFloat 2.2s ease-in-out infinite;
}
.preloader-mascot img{
  width:150px;
  filter:drop-shadow(0 0 28px rgba(205,100,255,.9));
}
.preloader-logo{
  font-size:clamp(48px,7vw,92px);
  font-weight:950;
  letter-spacing:-.06em;
  color:#fff;
  position:relative;
  text-shadow:0 0 35px rgba(197,93,255,.8);
  overflow:hidden;
}
.preloader-logo::after{
  content:"";
  position:absolute;
  top:0;bottom:0;
  width:40%;
  left:-50%;
  background:linear-gradient(90deg,transparent,rgba(255,255,255,.9),transparent);
  transform:skewX(-18deg);
  animation:logoShine 1.05s ease-in-out infinite;
}
.preloader-text{
  color:#e8d6ff;
  letter-spacing:.26em;
  font-weight:900;
  font-size:13px;
}
@keyframes preFloat{0%,100%{transform:translateY(0) scale(1)}50%{transform:translateY(-16px) scale(1.04)}}
@keyframes logoShine{to{left:120%}}

